+                return true;
+            case "reject":
+            case "rejected":
+            case "deny":
+            case "denied":
+            case "decline":
+            case "declined":
+                decision = ResolutionAction.Rejected;
+                return true;
+            default:
+                return false;
+        }
+    }
+}

